# -*- coding: utf-8 -*-
"""SkiaBoard 教程库生成器
将紧凑的教程数据编译为规范 lessons.js。
每篇教程 = id/title/学段/emoji/难度/时长/简介 + parts(逐步绘制指令)
生成器自动展开为: steps[i] 绘制 parts[0..i], finalDraw 绘制全部。
"""
import json

# ---------- 绘制指令构造器 ----------
def c(x, y, r, f='', s='', sw=3):   # 圆
    return ('c', x, y, r, f, s, sw)
def e(cx, cy, rx, ry, f='', s='', sw=3, rot=0):  # 椭圆
    return ('e', cx, cy, rx, ry, f, s, sw, rot)
def l(x1, y1, x2, y2, s='#333', sw=3):  # 直线
    return ('l', x1, y1, x2, y2, s, sw)
def r(x, y, w, h, f='', s='', sw=3):    # 矩形
    return ('r', x, y, w, h, f, s, sw)
def a(x, y, rad, a0, a1, s='#333', sw=3, f=''):  # 圆弧(兼容描边/填充)
    # a(...,stroke,sw) 描边；a(...,fill,stroke,sw) 填充+描边
    if isinstance(sw, str):  # 填充形式: s=fill, sw=stroke, f=width
        return ('a', x, y, rad, a0, a1, s, sw, f)
    return ('a', x, y, rad, a0, a1, '', s, sw)  # 描边形式
def p(pts, f='', s='', sw=3):           # 多边形
    return ('p', pts, f, s, sw)

# ---------- 常用子图模板(返回指令列表) ----------
def happy_eyes(x, y, dx=24, up=True):
    """一对弯弯的笑眼"""
    out = []
    for sgn in (-1, 1):
        if up:
            out.append(a(x+sgn*dx, y, 12, 0.05*3.14159, 0.95*3.14159, '#333', 3))
        else:
            out.append(a(x+sgn*dx, y, 12, 1.05*3.14159, 1.95*3.14159, '#333', 3))
    return out
def dot_eyes(x, y, dx=22, col='#333'):
    return [c(x-dx, y, 5, col), c(x+dx, y, 5, col)]
def smile(x, y, w=22, up=True):
    if up:
        return [a(x, y, w, 0.15*3.14159, 0.85*3.14159, '#333', 3)]
    return [a(x, y, w, 1.15*3.14159, 1.85*3.14159, '#333', 3)]
def blush(x, y, dx=30, dy=16):
    return [c(x-dx, y+dy, 9, 'rgba(255,150,150,0.55)'), c(x+dx, y+dy, 9, 'rgba(255,150,150,0.55)')]
def leaf(x, y, rx, ry, rot=-0.5, f='#2ECC71', s='#27AE60'):
    return [e(x, y, rx, ry, f, s, 2, rot)]
def petal(x, y, rx, ry, rot, f, s=''):
    return [e(x, y, rx, ry, f, s, 2, rot)]

# ---------- 教程列表 ----------
LESSONS = []
def add(group, label, lesson):
    lesson['ageGroup'] = group
    lesson['ageLabel'] = label
    LESSONS.append(lesson)

