# =========================================================
# 编译输出：LESSONS -> lessons.js
# =========================================================
import math, re

def _norm(t):
    """规整 e() 第5参歧义：数字=rot、字符串=fill。"""
    if t[0] != 'e':
        return t
    cx, cy, rx, ry = t[1], t[2], t[3], t[4]
    tail = list(t[5:])
    rot, f, s, sw = 0, '', '', 3
    if tail and isinstance(tail[0], (int, float)) and not isinstance(tail[0], bool):
        rot = tail[0]
        tail = tail[1:]
    if tail:
        f = tail[0]
    if len(tail) > 1:
        s = tail[1]
    if len(tail) > 2:
        sw = tail[2]
    return ('e', cx, cy, rx, ry, f, s, sw, rot)

def _fmt(v):
    if isinstance(v, float):
        r = round(v, 4)
        if r == 0:
            r = 0.0
        return repr(r)
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        return json.dumps(v, ensure_ascii=False)
    if isinstance(v, (list, tuple)):
        return '[' + ','.join(_fmt(x) for x in v) + ']'
    return repr(v)

def _emit_op(o):
    o = _norm(o)
    return '[' + ','.join(_fmt(x) for x in o) + ']'

def _emit_ops(ops):
    return '[' + ','.join(_emit_op(o) for o in ops) + ']'

def _expand(lesson):
    """按 parts 展开 steps/finalDraw。"""
    steps = []
    acc = []
    for part in lesson['parts']:
        acc.extend(part['d'])
        steps.append({'hint': part['hint'], 'ops': list(acc)})
    return steps, list(acc)

def _emit_lesson(lesson):
    steps, final = _expand(lesson)
    step_js = ','.join(
        "{hint:%s,draw:function(ctx){DRAW(ctx,%s)}}" % (_fmt(s['hint']), _emit_ops(s['ops']))
        for s in steps
    )
    diff = lesson.get('diff', 3)
    dur = lesson.get('dur', 5)
    return ("{id:%s,title:%s,ageGroup:%s,ageLabel:%s,difficulty:%d,duration:%d,"
            "emoji:%s,description:%s,steps:[%s],finalDraw:function(ctx){DRAW(ctx,%s)}}") % (
        _fmt(lesson['id']), _fmt(lesson['title']), _fmt(lesson['ageGroup']),
        _fmt(lesson['ageLabel']), diff, dur, _fmt(lesson.get('emoji', '✏️')),
        _fmt(lesson.get('desc', '')), step_js, _emit_ops(final)
    )

def compile_lessons():
    body = ','.join(_emit_lesson(l) for l in LESSONS)
    return (
        "/* 由 gen_lessons.py 自动生成，请勿手工编辑。共 "+str(len(LESSONS))+" 篇教程。 */\n"
        "window.LESSONS=(function(){\n"
        "function sh(c,f,s,w){if(f){c.fillStyle=f;c.fill();}if(s){c.strokeStyle=s;c.lineWidth=w||3;c.stroke();}}\n"
        "function DRAW(c,ops){for(var i=0;i<ops.length;i++){var o=ops[i],t=o[0];\n"
        "if(t==='c'){c.beginPath();c.arc(o[1],o[2],o[3],0,6.2832);sh(c,o[4],o[5],o[6]);}\n"
        "else if(t==='e'){c.beginPath();c.ellipse(o[1],o[2],o[3],o[4],o[8],0,6.2832);sh(c,o[5],o[6],o[7]);}\n"
        "else if(t==='l'){c.beginPath();c.moveTo(o[1],o[2]);c.lineTo(o[3],o[4]);sh(c,'',o[5],o[6]);}\n"
        "else if(t==='r'){c.beginPath();c.rect(o[1],o[2],o[3],o[4]);sh(c,o[5],o[6],o[7]);}\n"
        "else if(t==='a'){c.beginPath();c.arc(o[1],o[2],o[3],o[4],o[5]);sh(c,o[6],o[7],o[8]);}\n"
        "else if(t==='p'){var q=o[1];c.beginPath();c.moveTo(q[0][0],q[0][1]);for(var j=1;j<q.length;j++){c.lineTo(q[j][0],q[j][1]);}c.closePath();sh(c,o[2],o[3],o[4]);}\n"
        "}}\n"
        "return [\n" + body + "\n];\n})();\n"
    )

if __name__ == '__main__':
    from collections import Counter
    groups = Counter(l['ageGroup'] for l in LESSONS)
    print('学段数量:', dict(groups), '总篇数:', len(LESSONS))
    # 生成校验：每个学段 >= 100
    for g in ('kindergarten', 'primary', 'middle', 'adult'):
        n = groups.get(g, 0)
        flag = 'OK' if n >= 100 else '!!不足!!'
        print(f'  {g}: {n} {flag}')
        assert n >= 100, f'{g} 数量不足'
    out = compile_lessons()
    with open('lessons.js', 'w', encoding='utf-8') as f:
        f.write(out)
    print('已写出 lessons.js', len(out.splitlines()), '行')
